const today = new Date().toLocaleDateString('en-CA');
const active = (queries.records.data || []).filter(x => x.status === 'Active').sort((a, b) => notice(a).localeCompare(notice(b)));
const first = active[0];
const calendar = active.slice(0, 4).map(x => { const n = notice(x), past = n < today; return {
  id: x.id, month: new Date(n + 'T12:00:00').toLocaleDateString('en-US', {month: 'short'}).toUpperCase(), day: String(Number(n.slice(-2))),
