const open = (first?.tasks || []).filter(t => t.status !== 'Done').slice(0, 2).map(t => ({ title: t.title, owner: t.owner, status: t.status, color: t.status === 'Blocked' ? 'var(--cc-warning-systemStatus)' : 'var(--cc-primary-brand)', titleColor: 'var(--cc-primary-text)' }));
return { calendar, hasNext: !!first, nextId: first?.id ?? null,
  eyebrow: first ? 'NEXT DECISION / ' + first.reference : '', counterparty: first?.counterparty || '', nextMeta: first ? first.owner + ' · ' + first.notice_days + ' days notice' : '',
