  tasks: open.length ? open : [{ title: 'Review work is complete.', owner: '', status: '', color: 'var(--cc-success-systemStatus)', titleColor: 'var(--cc-success-systemStatus)' }] };

const money = n => '$' + (n / 100).toLocaleString('en-US', {maximumFractionDigits: 0});
