const r = (queries.records.data || []).find(x => x.id === variables.recordId);
const empty = [{ head: 'Select a contract to view its history.', note: '' }];
if (!r) return { has: false, eyebrow: '', name: 'Select a contract', meta: '', noticeDate: '', termEnds: '', value: '', history: empty, cycles: [] };
const history = (r.history || []).slice().reverse().map(h => ({ head: h.event + ' · ' + String(h.at || '').slice(0, 10), note: h.note || '' }));
return { has: true, eyebrow: 'CONTINUUM / ' + r.reference + ' / ' + String(r.status || '').toUpperCase(), name: r.name, meta: r.counterparty + ' · ' + r.owner,
  noticeDate: date(notice(r)), termEnds: 'Term ends ' + date(r.ends), value: money(r.value_cents),
  history: history.length ? history : empty,
  cycles: (r.cycles || []).slice().reverse().map(c => ({ head: 'Archived term ' + c.starts + ' → ' + c.ends, line1: '$' + (c.value_cents / 100).toFixed(2) + ' · ' + c.notice_days + ' days notice', terms: c.terms || '', line2: (c.tasks || []).length + ' review tasks retained · ' + (c.tasks || []).filter(t => t.status === 'Done').length + ' complete' })) };
